fun grade(score: Int): String = when {
    score >= 90 -> "A"
    score >= 80 -> "B"
    score >= 60 -> "C"
    else -> "D"
}

fun main() {
    println(grade(86))

    val x = 3
    when (x) {
        0, 1 -> println("小")
        in 2..5 -> println("中")
        else -> println("大")
    }

    val label = if (x > 0) "正" else "非正"
    println(label)
    println(grade(59))
}

tailrec fun factorial(n: Int, acc: Long = 1): Long =
    if (n <= 1) acc else factorial(n - 1, acc * n)

fun main() {
