interface Shape {
    fun area(): Double
    fun describe(): String = "面积 ${"%.2f".format(area())}"
}

abstract class BaseShape : Shape {
    abstract val name: String
    override fun describe(): String = "$name: ${super.describe()}"
}

class Circle(override val name: String, private val r: Double) : BaseShape() {
    override fun area(): Double = Math.PI * r * r
}

fun main() {
    val s: Shape = Circle("圆", 2.0)
    println(s.describe())
    println(s.area())
}

