}

class InsufficientFunds(val amount: Double) : Exception("余额不足：$amount")

fun withdraw(balance: Double, amount: Double): Double {
    require(amount > 0) { "金额必须为正" }
    if (amount > balance) throw InsufficientFunds(amount)
    return balance - amount
}

fun main() {
    try {
        println(withdraw(100.0, 150.0))
    } catch (e: InsufficientFunds) {
        println("捕获：${e.message}")
    } finally {
        println("结束")
    }

    val result = runCatching { withdraw(100.0, 30.0) }
    println(result.getOrNull())
    println(runCatching { withdraw(1.0, 5.0) }.exceptionOrNull()?.message)
}

