fun main() {
    val n = 1_000_000
    val list = ArrayList<Int>(n)
    var sum = 0L
    val t0 = System.nanoTime()

    for (i in 0 until n) {
        list.add(i)
    }
    for (v in list) {
        sum += v
    }

    val ms = (System.nanoTime() - t0) / 1_000_000
    println("sum=$sum, ${ms}ms")

    val seq = (1..n).asSequence().map { it * 2 }.take(5).toList()
    println(seq)
    val twice = { x: Int -> x * 2 }
    println(twice(21))
}

