sealed class Notification {
    data class Email(val to: String, val subject: String) : Notification()
    data class Sms(val phone: String, val text: String) : Notification()
}

fun render(n: Notification): String = when (n) {
    is Notification.Email -> "邮件 -> ${n.to}: ${n.subject}"
    is Notification.Sms -> "短信 -> ${n.phone}: ${n.text}"
}

object SmsSender {
    fun send(n: Notification.Sms) = "已发送 ${n.text}"
}

fun main() {
    val list = listOf(
        Notification.Email("a@b.com", "Hi"),
        Notification.Sms("13800000000", "验证码 1234"),
    )
    list.forEach { println(render(it)) }
    println(SmsSender.send(Notification.Sms("1", "test")))
}

