import java.security.MessageDigest
import java.util.Base64

fun hashPassword(password: String, salt: String): String {
    val digest = MessageDigest.getInstance("SHA-256")
    val bytes = digest.digest((salt + password).toByteArray())
    return Base64.getEncoder().encodeToString(bytes)
}

fun main() {
    val salt = "随机盐值"
    val h1 = hashPassword("secret", salt)
    println(h1)
    // 生产环境应使用 bcrypt/Argon2，并做恒定时间比较
    println(h1 == hashPassword("secret", salt))
    val dbPassword = System.getenv("DB_PASSWORD") ?: error("缺少 DB_PASSWORD")
    println(dbPassword.length)
}

import java.io.File
