fun main(args: Array<String>) {
    if (args.isEmpty()) {
        System.err.println("用法：java -jar app.jar <关键词> [文件]")
        exitProcess(64)
    }

    val keyword = args[0]
    val lines = if (args.size > 1) {
        File(args[1]).readLines()
    } else {
        generateSequence(::readLine).toList()
    }

    var hits = 0
    lines.forEachIndexed { i, line ->
        if (line.contains(keyword)) {
            hits++
            println("${i + 1}: $line")
        }
    }
    System.err.println("命中 $hits 行")
}

